using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Globalization;

namespace ZenStatesDebugTool.Theming
{
    /// <summary>
    /// A Lucide stroke icon (https://lucide.dev, ISC licence) on its 24x24 grid. The path data was generated from
    /// lucide-static 1.80.0 and holds only absolute M, L, C and Z commands (shapes and arcs are pre-converted),
    /// so WinForms can draw it without SVG support.
    /// </summary>
    public sealed class LucideIcon
    {
        private readonly List<PointF[]> figures = new List<PointF[]>();
        private readonly List<bool> closed = new List<bool>();
        private readonly List<byte[]> types = new List<byte[]>();

        public LucideIcon(string data)
        {
            Parse(data);
        }

        private void Parse(string data)
        {
            string[] tokens = data.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
            var points = new List<PointF>();
            var pointTypes = new List<byte>();
            int i = 0;
            PointF subpathStart = PointF.Empty;

            Func<float> next = () => float.Parse(tokens[i++], CultureInfo.InvariantCulture);

            System.Action flush = () =>
            {
                if (points.Count > 1)
                {
                    figures.Add(points.ToArray());
                    types.Add(pointTypes.ToArray());
                    closed.Add(false);
                }
                points.Clear();
                pointTypes.Clear();
            };

            while (i < tokens.Length)
            {
                string token = tokens[i];
                char command = token[0];
                tokens[i] = token.Substring(1);
                if (tokens[i].Length == 0)
                    i++;

                switch (command)
                {
                    case 'M':
                        flush();
                        subpathStart = new PointF(next(), next());
                        points.Add(subpathStart);
                        pointTypes.Add((byte)PathPointType.Start);
                        break;
                    case 'L':
                        StartIfNeeded(points, pointTypes, subpathStart);
                        points.Add(new PointF(next(), next()));
                        pointTypes.Add((byte)PathPointType.Line);
                        break;
                    case 'C':
                        StartIfNeeded(points, pointTypes, subpathStart);
                        for (int k = 0; k < 3; k++)
                        {
                            points.Add(new PointF(next(), next()));
                            pointTypes.Add((byte)PathPointType.Bezier);
                        }
                        break;
                    case 'Z':
                        if (points.Count > 1)
                        {
                            figures.Add(points.ToArray());
                            types.Add(pointTypes.ToArray());
                            closed.Add(true);
                        }
                        points.Clear();
                        pointTypes.Clear();
                        break;
                    default:
                        throw new FormatException("Unsupported path command " + command);
                }
            }

            flush();
        }

        // A segment right after Z continues from the start of the closed subpath
        private static void StartIfNeeded(List<PointF> points, List<byte> pointTypes, PointF start)
        {
            if (points.Count > 0)
                return;

            points.Add(start);
            pointTypes.Add((byte)PathPointType.Start);
        }

        /// <summary>Draws the icon centred in <paramref name="bounds"/>, scaled to <paramref name="size"/> pixels.</summary>
        public void Draw(Graphics g, RectangleF bounds, Color color, float size, float strokeWidth = 2f)
        {
            float scale = size / 24f;
            float left = bounds.Left + (bounds.Width - size) / 2f;
            float top = bounds.Top + (bounds.Height - size) / 2f;

            SmoothingMode previous = g.SmoothingMode;
            g.SmoothingMode = SmoothingMode.AntiAlias;

            using (var path = new GraphicsPath())
            using (var pen = new Pen(color, Math.Max(1f, strokeWidth * scale)))
            {
                pen.StartCap = LineCap.Round;
                pen.EndCap = LineCap.Round;
                pen.LineJoin = LineJoin.Round;

                for (int f = 0; f < figures.Count; f++)
                {
                    PointF[] source = figures[f];
                    var scaled = new PointF[source.Length];
                    for (int p = 0; p < source.Length; p++)
                        scaled[p] = new PointF(left + source[p].X * scale, top + source[p].Y * scale);

                    byte[] figureTypes = (byte[])types[f].Clone();
                    if (closed[f])
                        figureTypes[figureTypes.Length - 1] |= (byte)PathPointType.CloseSubpath;

                    path.AddPath(new GraphicsPath(scaled, figureTypes), false);
                }

                g.DrawPath(pen, path);
            }

            g.SmoothingMode = previous;
        }
    }

